ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	status: "SUCCESS",
	message: "Flight record created successfully in both local database and Salesforce",
	createdFlight: {
		ID: vars.dbFlightData.ID,
		code: vars.dbFlightData.code1,
		price: vars.dbFlightData.price default 0,
		departureDate: vars.dbFlightData.takeOffDate as String default "",
		origin: vars.dbFlightData.fromAirport default "",
		destination: vars.dbFlightData.toAirport default "",
		emptySeats: vars.dbFlightData.seatsAvailable default 0,
		plane: {
			"type": vars.dbFlightData.planeType default "",
			totalSeats: vars.dbFlightData.totalSeats default 0
		}
	},
	salesforceId: vars.salesforceId,
	localDatabaseId: vars.dbFlightData.ID,
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "VALIDATION_ERROR",
	error: "MISSING_REQUIRED_FIELDS",
	message: "Flight creation failed due to missing required fields",
	requiredFields: ["code", "origin", "destination"],
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "DUPLICATE_CODE_ERROR",
	error: "FLIGHT_CODE_EXISTS",
	message: "Flight with the provided code already exists",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "DATABASE_ERROR",
	error: "DATABASE_OPERATION_FAILED",
	message: "An error occurred while creating the flight record. Please try again later.",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "SALESFORCE_ERROR",
	error: "SALESFORCE_OPERATION_FAILED",
	message: "Flight was created in local database but failed to sync with Salesforce. Please try again or contact support.",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "ERROR",
	error: "UNEXPECTED_ERROR",
	message: "An unexpected error occurred while processing the request",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	notificationStatus: "ERROR",
	flightId: vars.flightId,
	error: vars.errorDescription,
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
	notificationType: "FLIGHT_UPDATE",
	recipient: {
		email: vars.passengerData.passenger_email,
		name: vars.passengerData.passenger_name
	},
	flightDetails: {
		flightId: vars.flightId,
		bookingId: vars.passengerData.booking_id,
		updatedFields: vars.updatePayload
	},
	message: "Your flight " ++ (vars.flightId as String) ++ " has been updated. Please check your booking for the latest details.",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
	message: "Flight " ++ (vars.flightId as String) ++ " updated successfully",
	updatedFlight: {
		ID: payload[0].ID,
		code: payload[0].code1,
		price: payload[0].price default 0,
		departureDate: payload[0].takeOffDate as String default "",
		origin: payload[0].fromAirport default "",
		destination: payload[0].toAirport default "",
		emptySeats: payload[0].seatsAvailable default 0,
		plane: {
			"type": payload[0].planeType default "",
			totalSeats: payload[0].totalSeats default 0
		}
	},
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}
